import math

def area_of_polygon_inside_circle(circle_radius, number_of_sides):
    # Calculate the area using the formula: (1/2) * n * r^2 * sin(2*pi/n)
    # This corresponds to summing the areas of n isosceles triangles with vertex angle 2*pi/n
    area = 0.5 * number_of_sides * (circle_radius ** 2) * math.sin(2 * math.pi / number_of_sides)
    return round(area, 3)

