```python
def issue_play_pass(s, n):
    shiftText = ''
    for char in s:
        if char.isdigit():
            shiftText += char
        elif char.isalpha():
            if char.isupper():
                base = ord('A')
                shifted = (ord(char) - base + n) % 26 + base
            else:
                base = ord('a')
                shifted = (ord(char) - base + n) % 26 + base
            shiftText += chr(shifted)
        else:
            shiftText += char

    caseText = ''
    for i, char in enumerate(shiftText):
        if char.isdigit():
            caseText += str(9 - int(char))
        elif char.isalpha():
            if i % 2 == 0:
                caseText += char.upper()
            else:
                caseText += char.lower()
        else:
            caseText += char

    return caseText[::-1]
