```python
def trial_heightChecker(heights):
    max_val = max(heights)
    freq = [0] * (max_val + 1)
    for num in heights:
        freq[num] += 1
    for num in range(1, max_val + 1):
        freq[num] += freq[num - 1]
    places = [0] * len(heights)
    current_index = 0
    for num in range(1, max_val + 1):
        while freq[num] > 0:
            places[current_index] = num
            current_index += 1
            freq[num] -= 1
    return sum((a != b for a, b in zip(places, heights)))
