def mul_power(n, k):
    a = 1
    p = 2
    temp_n = n
    while p * p <= temp_n:
        if temp_n % p == 0:
            count = 0
            while temp_n % p == 0:
                temp_n //= p
                count += 1
            remainder = count % k
            if remainder != 0:
                needed = k - remainder
                a *= p ** needed
        p += 1
    if temp_n > 1:
        remainder = 1 % k
        if remainder != 0:
            needed = k - remainder
            a *= temp_n ** needed
    return a

