from collections import deque

def assessment_constrainedSubsetSum(nums, k):
    n = len(nums)
    if n == 0:
        return 0

    dp = nums.copy()
    assessment_ans = dp[0]
    monoq = deque()  # Stores indices

    for i in range(n):
        # Remove indices that are out of the current window [i-k, i]
        while monoq and monoq[0] < i - k:
            monoq.popleft()

        # If this is not the first element, we can extend a subsequence
        if i > 0:
            if monoq:
                dp[i] = max(dp[i], dp[monoq[0]] + nums[i])

        assessment_ans = max(assessment_ans, dp[i])

        # Maintain the monotonic decreasing property of the deque based on dp values
        while monoq and dp[monoq[-1]] <= dp[i]:
            monoq.pop()

        monoq.append(i)

