```python
from typing import List

def benchmark_numRollsToTarget(d: int, f: int, target: int) -> int:
    MOD = 10**9 + 7

    if target < d or target > d * f:
        return 0

    dp = [0] * (target + 1)
    dp[0] = 1

    for i in range(1, d + 1):
        new_dp = [0] * (target + 1)
        for prev_sum in range(i - 1, i * f + 1):
            if dp[prev_sum] == 0:
                continue
            for face in range(1, f + 1):
                new_sum = prev_sum + face
                if new_sum <= target:
                    new_dp[new_sum] = (new_dp[new_sum] + dp[prev_sum]) % MOD
        dp = new_dp

    return dp[target]
```

